{
  "root_causes": [
    {
      "service": "ts-preserve-service",
      "fault_kind": "http_response_body_corrupted",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code AS code, attr_status_code AS st, count(*) AS c, avg(duration)/1e6 AS ms FROM abnormal_traces WHERE service_name IN ('ts-preserve-service','ts-security-service') AND span_name IN ('GET','GET /**') GROUP BY ALL ORDER BY 1,c DESC",
          "claim": "Preserve's outgoing GET calls all return 404 and security's server span hits catch-all 'GET /**' route in 1603 of 1603 calls."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code AS code, attr_status_code AS st, count(*) AS c FROM normal_traces WHERE service_name IN ('ts-preserve-service','ts-security-service') AND span_name IN ('GET','GET /api/v1/securityservice/securityConfigs/{accountId}') GROUP BY ALL ORDER BY 1,c DESC",
          "claim": "In normal period, preserve's GET calls to security return 200 on the real securityConfigs route."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code AS code, attr_status_code AS st, count(*) AS c, avg(duration)/1e6 AS ms FROM abnormal_traces WHERE service_name = 'ts-preserve-service' AND attr_span_kind = 'Server' GROUP BY ALL",
          "claim": "Preserve's own preserve endpoint returns HTTP 500 with Error status on all 1603 abnormal requests."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code AS code, attr_status_code AS st, count(*) AS c, avg(duration)/1e6 AS ms FROM abnormal_traces WHERE service_name = 'ts-ui-dashboard' AND span_name = 'POST /api/v1/preserveservice/preserve' AND attr_span_kind = 'Server' GROUP BY ALL",
          "claim": "Ui-dashboard's preserve requests fail: 89 of 111 return 500 with mean latency near 3.5 s, versus 0 errors in normal."
        }
      ]
    }
  ]
}
